"use client";

import { useCallback, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { useQuery } from "@tanstack/react-query";
import { Activity, AlertCircle, Check, Copy, Download, ExternalLink, FileText, LoaderCircle, LockKeyhole, RefreshCw, ShieldCheck, Sparkles, Trash2 } from "lucide-react";
import { api, dateLabel, fmt, send } from "./api";

type Notice = { kind: "success" | "error" | "info"; text: string } | null;
function NoticeBox({ notice }: { notice: Notice }) { if (!notice) return null; return <div className={`notice notice-${notice.kind}`} role="status">{notice.kind === "error" ? <AlertCircle size={16}/> : <Check size={16}/>}<span>{notice.text}</span></div>; }
function Panel({ title, aside, children }: { title: string; aside?: ReactNode; children: ReactNode }) { return <section className="panel workspace-panel"><div className="panel-header"><h2>{title}</h2>{aside}</div><div className="panel-body">{children}</div></section>; }
function Busy({ label = "Loading…" }: { label?: string }) { return <p className="loading-line"><LoaderCircle size={16} className="spin"/>{label}</p>; }
function Empty({ children }: { children: ReactNode }) { return <div className="workspace-empty"><Activity size={20}/><p>{children}</p></div>; }

export function PageAnalyzer() {
  const [data, setData] = useState<any>(null); const [loading, setLoading] = useState(false); const [notice, setNotice] = useState<Notice>(null);
  const run = async () => { setLoading(true); setNotice(null); try { const result = await api<any>("page/analyze", send("POST", {})); setData(result); setNotice({ kind: "success", text: "Page analysis completed using data returned by Meta. Unsupported insights remain unavailable." }); } catch (e) { setNotice({ kind: "error", text: e instanceof Error ? e.message : "Page analysis failed." }); } finally { setLoading(false); } };
  const loadLatest = useCallback(async () => { try { const result = await api<any>("page/snapshots"); const last = result.data?.[0]?.summary; if (last) setData(last); } catch { /* Empty state is intentional before first analysis. */ } }, []);
  useEffect(() => { void loadLatest(); }, [loadLatest]);
  return <div className="module-stack"><div className="module-intro"><div><span className="eyebrow">META GRAPH API / READ-ONLY ANALYSIS</span><h2>Facebook Page baseline</h2><p>Fetches the configured Page identity and recent posts. Insights availability depends on your token, Page permissions, and Meta API access.</p></div><button className="action-button" onClick={run} disabled={loading}>{loading ? <LoaderCircle size={15} className="spin"/> : <RefreshCw size={15}/>} Analyze Page</button></div><NoticeBox notice={notice}/>
    {loading && <Busy label="Requesting Page and post data from Meta…"/>}
    {data ? <><div className="metrics metrics-three"><div className="metric"><div className="metric-top">Connected Page</div><div className="metric-value metric-value-small">{data.page?.name || "Unknown"}</div><div className="metric-foot">Page ID: {data.page?.id || "—"}</div></div><div className="metric"><div className="metric-top">Recent posts checked</div><div className="metric-value">{fmt(data.coverage?.postCount)}</div><div className="metric-foot">Latest fetch: {dateLabel(data.fetchedAt)}</div></div><div className="metric"><div className="metric-top">Posts with insights</div><div className="metric-value">{fmt(data.coverage?.insightsAvailable)}</div><div className="metric-foot">Graph API v26 media-view metrics only; exact per-post reach is not reliably available.</div></div></div><Panel title="Recent Page posts" aside={<span className="eyebrow">{data.coverage?.hasMore ? "Latest 10 · more available" : "Fetched posts"}</span>}>{data.posts?.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Post</th><th>Date</th><th>Reactions</th><th>Comments</th><th>Shares</th><th>Unique media views</th><th>Media views</th><th>Link</th></tr></thead><tbody>{data.posts.map((post: any) => <tr key={post.id}><td className="post-cell">{post.message}</td><td>{dateLabel(post.createdAt)}</td><td>{fmt(post.reactions)}</td><td>{fmt(post.comments)}</td><td>{fmt(post.shares)}</td><td>{post.insights?.post_total_media_view_unique ?? "Unavailable"}</td><td>{post.insights?.post_media_view ?? "Unavailable"}</td><td>{post.permalink ? <a href={post.permalink} target="_blank" rel="noreferrer" aria-label="Open Facebook post"><ExternalLink size={15}/></a> : "—"}</td></tr>)}</tbody></table></div> : <Empty>No posts were returned by Meta for this Page.</Empty>}</Panel><p className="panel-note">This is a read-only fetch. It does not publish or modify Facebook content. Meta can deny individual insight metrics even when the Page identity is readable.</p></> : <Panel title="No imported baseline yet"><Empty>Choose Analyze Page to verify the token against Meta and fetch real data. Nothing is estimated or fabricated.</Empty></Panel>}</div>;
}

export function ContentStudio() {
  const [guidance, setGuidance] = useState(""); const [decision, setDecision] = useState<any>(null); const [items, setItems] = useState<any[]>([]); const [jobs, setJobs] = useState<any[]>([]); const [loading, setLoading] = useState(false); const [notice, setNotice] = useState<Notice>(null); const [checks, setChecks] = useState<Record<string, any>>({});
  const load = useCallback(async () => { try { const result = await api<any>("content"); setItems(result.data || []); } catch (e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load drafts."}); } }, []);
  const loadJobs = useCallback(async () => { try { const result = await api<any>("jobs?limit=20"); setJobs(result.data || []); } catch (e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load generation jobs."}); } }, []);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { void loadJobs(); }, [loadJobs]);
  useEffect(() => { void api<any>("agent/guidance").then(result => setGuidance(result.guidance || "")).catch(() => undefined); }, []);
  useEffect(() => { if (jobs.some(job => job.status === "COMPLETED")) void load(); }, [jobs, load]);
  useEffect(() => {
    if (!jobs.some(job => ["PENDING", "PROCESSING", "RETRY_WAIT"].includes(job.status))) return;
    const timer = window.setInterval(() => { void loadJobs(); }, 5000);
    return () => window.clearInterval(timer);
  }, [jobs, loadJobs]);
  async function generate(e: FormEvent) { e.preventDefault(); setLoading(true); setNotice(null); setDecision(null); try { const result = await api<any>("campaign/run", send("POST", { guidance })); const campaign = result.data || {}; if (campaign.published?.published) { setDecision({topic:campaign.topic,format:campaign.format,creativeAngle:campaign.creativeAngle,rationale:campaign.rationale,confidence:campaign.confidence}); setNotice({kind:"success",text:`Agent published ${campaign.format || campaign.published.mediaType} to Facebook. Post ID: ${campaign.published.postId || "accepted by Meta"}. It will review the outcome during the next scheduled cycle.`}); } else if (campaign.contentId && campaign.mode === "dry-run") { setDecision({topic:campaign.topic,format:campaign.format,creativeAngle:campaign.creativeAngle,rationale:campaign.rationale,confidence:campaign.confidence}); setNotice({kind:"info",text:`${campaign.reason} Preview saved as ${campaign.contentId}. Switch to live mode only after staging checks.`}); } else { setNotice({kind:"info",text:campaign.reason || campaign.published?.reason || "The agent decided not to publish in this run."}); } await load(); await loadJobs(); } catch (err) { setNotice({kind:"error",text:err instanceof Error?err.message:"The agent campaign could not finish. Check Meta permissions, AI quota, FFmpeg, and server logs."}); } finally { setLoading(false); } }
  async function reviewChecks(id:string) { try { const result = await api<any>(`content/${id}/checks`); setChecks(old=>({...old,[id]:result.data})); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not run the publish checks."}); } }
  async function confirmNotPublished(id:string) { if (!window.confirm("Open the Facebook Page and confirm this item is NOT live there. Mark it as not published so the agent can continue?")) return; try { await api(`content/${id}/resolve-publishing`,send("POST",{})); await load(); setNotice({kind:"success",text:"Marked as not published. The agent can continue once you re-enable Agent Mode."}); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not update the item."}); } }
  async function retryJob(id:string) { try { await api(`jobs/${id}/retry`,send("POST",{})); setNotice({kind:"info",text:"Job queued for another safe attempt."}); await loadJobs(); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not retry this job."}); } }
  async function changeStatus(id:string,status:string) { try { await api(`content/${id}`,send("PATCH",{status})); await load(); setNotice({kind:"success",text:status==="VALIDATED"?"Content marked reviewed. If a previous publishing attempt failed, check the Facebook Page for an existing post before trying again.":`Draft moved to ${status.toLowerCase()}.`}); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Update failed."}); } }
  async function remove(id:string) { if (!window.confirm("Delete this saved draft?")) return; try { await api(`content/${id}`,{method:"DELETE"}); await load(); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Delete failed."}); } }
  async function downloadAsset(item:any) { if (!item.assetUrl) return; try { const image = new Image(); image.src = item.assetUrl; await new Promise<void>((resolve,reject)=>{ image.onload=()=>resolve(); image.onerror=()=>reject(new Error("Could not render the generated creative.")); }); const canvas=document.createElement("canvas"); canvas.width=image.naturalWidth||1200; canvas.height=image.naturalHeight||1200; const context=canvas.getContext("2d"); if(!context) throw new Error("Canvas is unavailable."); context.drawImage(image,0,0,canvas.width,canvas.height); const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("PNG export failed.")),"image/png")); const url=URL.createObjectURL(blob); const link=document.createElement("a"); link.href=url; link.download=`tutorlink-${item.format.toLowerCase()}-${item.id}.png`; link.click(); window.setTimeout(()=>URL.revokeObjectURL(url),1000); setNotice({kind:"success",text:"PNG creative downloaded. Review it before manually uploading to Facebook."}); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not export the creative."}); } }
  async function copyDraft(item:any) { try { const tags=Array.isArray(item.hashtags)?item.hashtags.join(" "):""; await navigator.clipboard.writeText(`${item.caption}${tags?`\n\n${tags}`:""}`); setNotice({kind:"success",text:"Caption and hashtags copied. Review before publishing manually."}); } catch { setNotice({kind:"error",text:"Clipboard access was blocked by the browser."}); } }
  async function linkFacebookPost(item:any) { const postId=window.prompt("Paste the Facebook post ID only for a post that was published outside this app. Auto-published posts are linked automatically.",item.platformPostId||""); if(!postId?.trim())return; try { await api(`content/${item.id}/facebook-reference`,send("PATCH",{platformPostId:postId.trim()})); await load(); setNotice({kind:"success",text:"Facebook post ID linked. The next Page analysis can match available metrics to this content."}); } catch(e) { setNotice({kind:"error",text:e instanceof Error?e.message:"Could not link Facebook post ID."}); } }
  return <div className="module-stack"><Panel title="Autonomous Content Studio" aside={<span className="status-pill"><Sparkles size={13}/> Agent decides</span>}><form className="workspace-form" onSubmit={generate}><p className="panel-note">You do not need to choose a topic, format, audience, angle, or design. The agent reviews available Page insights, recent content, qualified leads and bookings, then decides whether to publish now or wait. If it publishes, it chooses the topic, audience, feed banner or Reel, creative angle and schedule. It saves your guidance for future automated cycles.</p><label>Guide the agent (optional)<textarea value={guidance} onChange={e=>setGuidance(e.target.value)} maxLength={1800} rows={4} placeholder="Example: This week, focus on guardians searching for a Class 8 mathematics tutor in Chattogram. Keep the tone warm and practical. The agent will follow this guidance while still choosing the format and creative approach."/></label><button className="action-button" type="submit" disabled={loading}>{loading?<LoaderCircle size={15} className="spin"/>:<Sparkles size={15}/>} {loading?"Agent is analyzing and creating…":"Let the agent decide and publish (or wait)"}</button><p className="panel-note">The agent prioritizes qualified enquiries and bookings over likes. Your guidance is saved for future runs. The campaign publishes only when Meta live mode is enabled, the Page/Messenger configuration is valid, and the agent decides the cadence is appropriate. Reels are rendered into MP4 and uploaded through the Meta Reels Publishing API.</p></form></Panel><NoticeBox notice={notice}/>{decision&&<Panel title="Why the agent chose this"><div className="readiness-list"><div><strong>{decision.topic}</strong><p className="panel-note">{decision.format} · {String(decision.creativeAngle||"").replaceAll("_"," ")} · confidence {Math.round((decision.confidence||0)*100)}%</p><p>{decision.rationale}</p></div></div></Panel>}<Panel title="Generation jobs" aside={<button className="subtle-button" onClick={loadJobs}><RefreshCw size={13}/> Refresh</button>}>{jobs.length ? <div className="draft-list">{jobs.map(job=><article className="draft-card" key={job.id}><div className="draft-top"><div><span className="eyebrow">{job.jobKey} / {job.status} · attempt {job.attemptCount}/{job.maxAttempts}</span><h3>{job.result?.contentId ? `Draft saved: ${job.result.contentId}` : job.status === "COMPLETED" ? "Generation completed" : "Content generation"}</h3></div><span className="panel-note">{job.completedAt ? `Completed ${dateLabel(job.completedAt)}` : job.status === "RETRY_WAIT" ? `Retry after ${dateLabel(job.nextAttemptAt)}` : `Updated ${dateLabel(job.updatedAt)}`}</span></div>{job.result?.provider && <p className="panel-note">Provider/model: {job.result.provider} / {job.result.model || "not recorded"}{job.result.fallbackFrom ? ` (fallback from ${job.result.fallbackFrom})` : ""}</p>}{job.lastErrorCategory && <NoticeBox notice={{kind:"error",text:`${job.lastErrorCategory}: ${job.errorMessage || "Review server configuration and retry status."}`}}/>}{job.status === "NEEDS_ATTENTION" && <p className="panel-note">Action required before retry: check provider credentials, permissions, or quota reset.</p>}{job.status === "FAILED" && <button className="subtle-button" onClick={()=>retryJob(job.id)}>Retry job</button>}</article>)}</div> : <Empty>No generation jobs yet. Jobs are saved and can recover automatically after a restart.</Empty>}</Panel><Panel title="Saved content drafts" aside={<button className="subtle-button" onClick={load}><RefreshCw size={13}/> Refresh</button>}>{items.length ? <div className="draft-list">{items.map(item=><article className="draft-card" key={item.id}><div className="draft-top"><div><span className="eyebrow">{item.format} / {item.status} · {String(item.creativeAngle||"AUTO").replaceAll("_"," ")} · {String(item.visualStyle||"legacy").replaceAll("_"," ")}</span><h3>{item.title}</h3></div><button className="icon-button danger" onClick={()=>remove(item.id)} aria-label="Delete draft"><Trash2 size={15}/></button></div>{item.assetUrl && <div className="draft-asset"><img src={item.assetUrl} alt={`${item.title} branded ${item.format === "REEL" ? "Reel cover" : "Facebook banner"}`} loading="lazy"/><p className="panel-note">{item.format === "REEL" ? `Vertical Reel cover · ${String(item.visualStyle||"legacy").replaceAll("_"," ")} · Reel MP4 is rendered when publishing` : `Square feed banner · ${String(item.visualStyle||"legacy").replaceAll("_"," ")} template`}</p></div>}<p className="draft-caption">{item.caption}</p>{Array.isArray(item.hashtags)&&item.hashtags.length>0&&<p className="draft-hashtags">{item.hashtags.join(" ")}</p>}{Array.isArray(item.reelScenes)&&item.reelScenes.length>0&&<details><summary>On-screen Reel scenes ({item.reelScenes.length + 2} frames incl. hook and contact end card)</summary><ol className="plain-list">{item.reelScenes.map((line:string,i:number)=><li key={i}>{line}</li>)}</ol></details>}{item.script && <details><summary>Reel script / storyboard</summary><p className="draft-caption">{item.script}</p></details>}{checks[item.id]&&<ChecksView data={checks[item.id]}/>}<div className="draft-bottom"><span className="panel-note">Created {dateLabel(item.createdAt)}</span><div className="button-row"><button className="subtle-button" onClick={()=>downloadAsset(item)} disabled={!item.assetUrl}><Download size={13}/> Download PNG</button><button className="subtle-button" onClick={()=>reviewChecks(item.id)}><ShieldCheck size={13}/> Review publish checks</button><button className="subtle-button" onClick={()=>copyDraft(item)}><Copy size={13}/> Copy caption + hashtags</button>{["PUBLISHING","FAILED"].includes(item.status)&&!item.platformPostId&&<button className="subtle-button" onClick={()=>confirmNotPublished(item.id)}>Confirm not on Facebook</button>}{["DRAFT","VALIDATED","SCHEDULED"].includes(item.status)&&<button className="subtle-button" onClick={async()=>{try{const result=await api<any>(`content/${item.id}/publish`,send("POST",{}));setNotice({kind:"success",text:`Published to Facebook. Post ID: ${result.data?.postId||"accepted by Meta"}`});await load();}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Facebook publishing failed."});}}}><ExternalLink size={13}/> Publish to Facebook</button>}<button className="subtle-button" onClick={()=>linkFacebookPost(item)}><ExternalLink size={13}/> Link existing FB post ID</button>{item.status!=="VALIDATED"&&<button className="subtle-button" onClick={()=>changeStatus(item.id,"VALIDATED")}>Mark reviewed</button>}{item.status!=="PAUSED"&&<button className="subtle-button" onClick={()=>changeStatus(item.id,"PAUSED")}>Pause draft</button>}</div></div></article>)}</div>:<Empty>No saved drafts yet. Generate a draft above to start the content library.</Empty>}</Panel></div>;
}

export function PublishingCalendar() {
  const [items,setItems]=useState<any[]>([]); const [notice,setNotice]=useState<Notice>(null); const [busy,setBusy]=useState(false);
  const load=useCallback(async()=>{try{const result=await api<any>("content");setItems((result.data||[]).filter((x:any)=>["SCHEDULED","DRAFT","VALIDATED","PAUSED"].includes(x.status)));}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load calendar."});}},[]);
  useEffect(()=>{void load();},[load]);
  const [planFor,setPlanFor]=useState<string|null>(null);const [planValue,setPlanValue]=useState("");
  async function schedule(id:string){const date=new Date(planValue);if(!planValue||Number.isNaN(date.getTime())||date.getTime()<Date.now()){setNotice({kind:"error",text:"Choose a future date and time."});return;}setBusy(true);try{await api(`content/${id}`,send("PATCH",{status:"SCHEDULED",scheduledAt:date.toISOString()}));setPlanFor(null);setPlanValue("");setNotice({kind:"success",text:"Draft scheduled. The daily Cron publishes it on the first campaign run after its due time; with Vercel Hobby (one run per day) it may go out later than the exact time chosen."});await load();}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not schedule draft."});}finally{setBusy(false);}}
  async function pause(id:string){try{await api(`content/${id}`,send("PATCH",{status:"PAUSED"}));await load();}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not pause draft."});}}
  return <div className="module-stack"><div className="module-intro"><div><h2>Draft planning calendar</h2><p>Review and schedule content. Due scheduled posts are automatically published when live mode is enabled and Meta configuration passes validation.</p></div><button className="subtle-button" onClick={load}><RefreshCw size={14}/> Refresh</button></div><NoticeBox notice={notice}/><Panel title="Content queue" aside={<span className="eyebrow">{items.length} items</span>}>{items.length?<div className="calendar-list">{items.map(item=><article className="calendar-item" key={item.id}><div className="calendar-date"><span>{item.scheduledAt?new Date(item.scheduledAt).toLocaleDateString(undefined,{month:"short",day:"numeric"}):item.status}</span><small>{item.scheduledAt?new Date(item.scheduledAt).toLocaleTimeString(undefined,{hour:"2-digit",minute:"2-digit"}):"Not scheduled"}</small></div><div className="calendar-content"><strong>{item.title}</strong><p>{item.caption}</p><span className="eyebrow">{item.format} / {item.status}</span></div><div className="button-row">{item.status!=="SCHEDULED"&&(planFor===item.id?<><input type="datetime-local" className="inline-select" aria-label="Publish date and time" value={planValue} onChange={e=>setPlanValue(e.target.value)}/><button className="subtle-button" disabled={busy} onClick={()=>schedule(item.id)}>Schedule</button><button className="subtle-button" onClick={()=>setPlanFor(null)}>Cancel</button></>:<button className="subtle-button" disabled={busy} onClick={()=>{setPlanFor(item.id);setPlanValue("");}}>Plan</button>)}{item.status==="SCHEDULED"&&<button className="subtle-button" onClick={()=>pause(item.id)}>Pause</button>}</div></article>)}</div>:<Empty>There are no drafts in the queue yet. Create content in Content Studio first.</Empty>}</Panel><div className="notice notice-info"><ShieldCheck size={16}/><span>Safety: due items publish automatically only in live mode. Agent Mode defaults OFF; paused automation never publishes.</span></div></div>;
}

export function QualifiedLeads() {
  const [leads,setLeads]=useState<any[]>([]);const [notice,setNotice]=useState<Notice>(null);const [saving,setSaving]=useState(false);
  const [form,setForm]=useState({contactName:"",contactChannel:"MESSENGER",serviceArea:"",classLevel:"",qualificationReason:"",status:"NEW",sourceContentId:""});const [contentItems,setContentItems]=useState<any[]>([]);
  const load=useCallback(async()=>{try{const [result,content]=await Promise.all([api<any>("leads"),api<any>("content")]);setLeads(result.data||[]);setContentItems(content.data||[]);}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load leads."});}},[]);useEffect(()=>{void load();},[load]);
  async function add(e:FormEvent){e.preventDefault();setSaving(true);try{const payload={...form,sourceContentId:form.sourceContentId||undefined};await api("leads",send("POST",payload));setForm({contactName:"",contactChannel:"MESSENGER",serviceArea:"",classLevel:"",qualificationReason:"",status:"NEW",sourceContentId:""});setNotice({kind:"success",text:"Lead record saved."});await load();}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not save lead."});}finally{setSaving(false);}}
  async function setStatus(id:string,status:string){try{await api(`leads/${id}`,send("PATCH",{status}));await load();setNotice({kind:"success",text:"Lead status updated."});}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not update lead."});}}
  return <div className="module-stack"><Panel title="Record a qualified enquiry"><form className="workspace-form" onSubmit={add}><div className="form-grid"><label>Guardian name (optional)<input value={form.contactName} maxLength={120} onChange={e=>setForm({...form,contactName:e.target.value})}/></label><label>Contact channel<select value={form.contactChannel} onChange={e=>setForm({...form,contactChannel:e.target.value})}><option value="MESSENGER">Messenger</option><option value="PHONE">Phone</option><option value="WHATSAPP">WhatsApp</option><option value="OTHER">Other</option></select></label><label>Area<input value={form.serviceArea} maxLength={180} onChange={e=>setForm({...form,serviceArea:e.target.value})}/></label><label>Class / level<input value={form.classLevel} maxLength={80} onChange={e=>setForm({...form,classLevel:e.target.value})}/></label></div><label>Source content (if known)<select value={form.sourceContentId} onChange={e=>setForm({...form,sourceContentId:e.target.value})}><option value="">Unknown / not attributed</option>{contentItems.map((item:any)=><option key={item.id} value={item.id}>{item.title} · {item.format} · {item.status}</option>)}</select></label><label>Qualification notes<textarea value={form.qualificationReason} maxLength={1000} rows={3} onChange={e=>setForm({...form,qualificationReason:e.target.value})} placeholder="Required subjects, guardian intent, schedule needs…"/></label><button className="action-button" disabled={saving}>{saving?<LoaderCircle size={15} className="spin"/>:<Check size={15}/>} Save lead</button></form></Panel><NoticeBox notice={notice}/><Panel title="Lead pipeline" aside={<button className="subtle-button" onClick={load}><RefreshCw size={13}/> Refresh</button>}>{leads.length?<div className="table-wrap"><table className="data-table"><thead><tr><th>Lead</th><th>Area</th><th>Class</th><th>Channel</th><th>Status</th><th>Created</th></tr></thead><tbody>{leads.map(lead=><tr key={lead.id}><td>{lead.contactName||"Guardian (unnamed)"}<small className="table-subtext">{lead.qualificationReason||"No qualification notes"}</small>{lead.sourceContentId&&<small className="table-subtext">Attributed to a post{typeof lead.attributionConfidence==="number"?` · ${Math.round(lead.attributionConfidence*100)}% confidence`:""}</small>}{lead.notes&&<details><summary>Enquiry text (admin only)</summary><p className="draft-caption">{lead.notes}</p></details>}</td><td>{lead.serviceArea||"—"}</td><td>{lead.classLevel||"—"}</td><td>{lead.contactChannel||"—"}</td><td><select className="inline-select" aria-label={`Status for ${lead.contactName||"lead"}`} value={lead.status} onChange={e=>setStatus(lead.id,e.target.value)}>{["NEW","QUALIFIED","UNQUALIFIED","CONTACTED","BOOKED","LOST"].map(s=><option key={s}>{s}</option>)}</select></td><td>{dateLabel(lead.createdAt)}</td></tr>)}</tbody></table></div>:<Empty>No lead records yet. Add only enquiries you are authorized to store.</Empty>}</Panel><p className="panel-note">Privacy note: enquiry text is visible to signed-in admins only so you can correct the AI label. Phone numbers and emails are redacted before any text reaches an AI model. Only store what you need for follow-up.</p></div>;
}

export function StrategyLab() {
  const [data,setData]=useState<any>(null);const [learning,setLearning]=useState<any[]>([]);const [notice,setNotice]=useState<Notice>(null);const [form,setForm]=useState({name:"",hypothesis:"",variable:""});
  const load=useCallback(async()=>{try{api<any>("strategy/learning").then(r=>setLearning(r.data||[])).catch(()=>undefined);setData(await api("strategy/experiments"));}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load strategy data."});}},[]);useEffect(()=>{void load();},[load]);
  async function add(e:FormEvent){e.preventDefault();try{await api("strategy/experiments",send("POST",form));setForm({name:"",hypothesis:"",variable:""});setNotice({kind:"success",text:"Experiment saved. It will not run automatically."});await load();}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not save experiment."});}}
  async function update(id:string,status:string){try{await api(`strategy/experiments/${id}`,send("PATCH",{status}));await load();}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not update experiment."});}}
  return <div className="module-stack"><Panel title="Evidence-based recommendation"><div className="recommendation"><ShieldCheck size={22}/><div><strong>{data?.baselineAvailable?"Baseline available":"Baseline required"}</strong><p>{data?.recommendation||"Loading current evidence…"}</p><small>Qualified leads recorded: {fmt(data?.qualifiedLeadCount)} · Last baseline: {dateLabel(data?.latestBaselineAt)}</small></div></div></Panel><NoticeBox notice={notice}/><Panel title="What the agent has learned (per variant)">{learning.length?<div className="table-wrap"><table className="data-table"><thead><tr><th>Variable</th><th>Variant</th><th>Posts</th><th>Qualified / booked leads</th><th>Unique media views</th></tr></thead><tbody>{learning.map((g:any)=><tr key={`${g.experimentKey}:${g.variant}`}><td>{g.experimentKey}</td><td>{String(g.variant).replaceAll("_"," ")}</td><td>{fmt(g.posts)}</td><td>{fmt(g.qualified)} / {fmt(g.booked)}</td><td>{fmt(g.views)}</td></tr>)}</tbody></table></div>:<Empty>No published posts have been recorded yet. Every autonomous post logs its format, angle and style here so results can be compared.</Empty>}<p className="panel-note">Small samples are exploration, not proof. The agent only favours an angle after 2+ measured posts with a positive lead score.</p></Panel><Panel title="Create one controlled experiment"><form className="workspace-form" onSubmit={add}><label>Experiment name<input required minLength={3} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Hypothesis<textarea required minLength={5} rows={2} value={form.hypothesis} onChange={e=>setForm({...form,hypothesis:e.target.value})} placeholder="If we change X for audience Y, qualified enquiries may improve because…"/></label><label>Single variable to test<input required value={form.variable} onChange={e=>setForm({...form,variable:e.target.value})} placeholder="e.g. opening hook"/></label><button className="action-button">Save experiment</button></form></Panel><Panel title="Experiment log">{data?.data?.length?<div className="draft-list">{data.data.map((x:any)=><article className="draft-card" key={x.id}><div className="draft-top"><div><span className="eyebrow">{x.status} · {x.variable}</span><h3>{x.name}</h3></div></div><p>{x.hypothesis}</p><div className="button-row">{x.status==="PLANNED"&&<button className="subtle-button" onClick={()=>update(x.id,"RUNNING")}>Start test</button>}{x.status==="RUNNING"&&<button className="subtle-button" onClick={()=>update(x.id,"COMPLETED")}>Mark complete</button>}</div></article>)}</div>:<Empty>No experiments recorded. Wait for a baseline before making performance claims.</Empty>}</Panel></div>;
}

export function SettingsModule() {
  const [settings,setSettings]=useState<any>(null);const [notice,setNotice]=useState<Notice>(null);const [busy,setBusy]=useState(false);
  const load=useCallback(async()=>{try{setSettings(await api("settings"));}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load settings."});}},[]);useEffect(()=>{void load();},[load]);
  async function safety(patch:Record<string,unknown>){setBusy(true);setNotice(null);try{const result=await api<any>("settings/safety",send("PATCH",patch));setSettings((old:any)=>({...old,...result}));setNotice({kind:"success",text:"Safety settings updated on the server. Live publishing requires META_PUBLISH_MODE=live and valid Meta permissions."});}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not update safety settings."});}finally{setBusy(false);}}
  async function toggleAgent(){if(!settings)return;if(!settings.agentMode){if(!window.confirm("Enable Agent Mode? When live publishing is configured, the agent may publish public Facebook posts and Reels without asking you first. You can switch it OFF here at any time."))return;await safety({globalAutomationPaused:false,agentMode:true,confirmation:"ENABLE_AGENT_MODE"});}else{await safety({agentMode:false});}}
  return <div className="module-stack"><NoticeBox notice={notice}/><Panel title="Safety controls" aside={<span className="status-pill"><LockKeyhole size={13}/> Server enforced</span>}><div className="settings-list"><div className="setting-row"><div><strong>Global automation pause</strong><p>When paused, Agent Mode is forced OFF. The initial state is paused.</p><span className={`state-chip ${settings?.globalAutomationPaused!==false?"state-warn":"state-ok"}`}>{settings?.globalAutomationPaused!==false?"PAUSED":"UNPAUSED"}</span></div><button className="subtle-button" disabled={busy||!settings} onClick={()=>safety({globalAutomationPaused:!settings.globalAutomationPaused})}>{settings?.globalAutomationPaused===false?"Pause system":"Unpause system"}</button></div><div className="setting-row"><div><strong>Agent Mode</strong><p>Enables the autonomous campaign: lead-first decision, content creation, and automatic Facebook publishing when live mode and Meta permissions are configured.</p><span className={`state-chip ${settings?.agentMode?"state-ok":"state-warn"}`}>{settings?.agentMode?"ON":"OFF"}</span></div><button className="subtle-button" disabled={busy||!settings} onClick={toggleAgent}>{settings?.agentMode?"Turn OFF":"Turn ON"}</button></div></div></Panel><Panel title="Integration readiness"><div className="readiness-list"><Readiness name="Facebook Page credentials" ready={Boolean(settings?.integrations?.metaConfigured)} detail={settings?.integrations?.metaConfigured?"Credentials exist; test actual Page access in Page Analyzer.":"Add META_PAGE_ID and META_PAGE_ACCESS_TOKEN to apps/api/.env."}/><Readiness name="AI provider" ready={Boolean(settings?.integrations?.aiConfigured)} detail={`${settings?.integrations?.aiProvider||"unknown"} · ${settings?.integrations?.aiModel||"model not set"}. Configured does not guarantee successful generation.`}/><Readiness name="Publishing" ready={settings?.publishMode==="live"} detail={`Configured mode: ${settings?.publishMode||"unknown"}. Automatic publishing is enabled only when META_PUBLISH_MODE=live and the verified Messenger URL is configured.`}/><Readiness name="Messenger conversion URL" ready={Boolean(settings?.integrations?.messengerConfigured)} detail={settings?.integrations?.messengerConfigured?"Verified URL is configured and included with every caption.":"Set META_MESSENGER_URL to the verified Page m.me URL; publishing is blocked until configured."}/><Readiness name="Database" ready detail="Authenticated requests can reach the configured API and database when data actions succeed."/></div></Panel><AiHealthPanel settings={settings}/><DiagnosticsPanel/><BusinessProfilePanel/><p className="panel-note">Secrets are never returned by this endpoint. Never paste access tokens or database URLs into screenshots or chat.</p></div>;
}
function Readiness({name,ready,detail}:{name:string;ready:boolean;detail:string}){return <div className="readiness-item"><span className={`readiness-icon ${ready?"ready":"pending"}`}>{ready?<Check size={14}/>:<AlertCircle size={14}/>}</span><div><strong>{name}</strong><p>{detail}</p></div></div>;}

export function PerformanceMonitor() {
 const [data,setData]=useState<any>(null);const [notice,setNotice]=useState<Notice>(null);const [running,setRunning]=useState(false);
 const load=useCallback(async()=>{try{setData(await api("performance"));}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load performance history."});}},[]);
 useEffect(()=>{void load();},[load]);
 async function monitor(){setRunning(true);setNotice(null);try{const result=await api<any>("performance/monitor",send("POST",{}));await load();setNotice({kind:"success",text:`Monitoring completed for ${result.data?.page?.name||"the configured Facebook Page"}. The next autonomous campaign will use this snapshot if automation is enabled.`});}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Performance monitoring failed. Check Meta permissions."});}finally{setRunning(false);}}
 const metrics=data?.metrics;const leads=data?.leads;const recs=data?.latestRecommendations||[];
 return <div className="module-stack"><div className="module-intro"><div><span className="eyebrow">PERFORMANCE / LEAD-QUALITY LOOP</span><h2>Monitor organic growth</h2><p>Compare available Facebook insights with recorded tuition enquiries. Missing Meta metrics stay unknown, never zero.</p></div><button className="action-button" onClick={monitor} disabled={running}>{running?<LoaderCircle size={15} className="spin"/>:<RefreshCw size={15}/>} {running?"Checking…":"Run monitor now"}</button></div><NoticeBox notice={notice}/>
 <div className="metrics metrics-five"><Metric label="Posts sampled" value={fmt(metrics?.postCount)} foot="Recent posts returned by Meta"/><Metric label="Posts with insights" value={fmt(metrics?.insightsAvailable)} foot="Usable post-level insight data"/><Metric label="Unique media views" value={fmt(metrics?.uniqueMediaViews)} foot={metrics?.uniqueMediaViews==null?"Unavailable — check Meta permissions":"Unique media views are a proxy, not exact reach"}/><Metric label="Media views" value={fmt(metrics?.mediaViews)} foot={metrics?.mediaViews==null?"Unavailable until Meta returns media-view insights":"Total media-view values returned by Meta"}/><Metric label="Qualified / booked leads" value={fmt(leads?.qualifiedOrBookedLast7Days)} foot={`${fmt(leads?.bookedLast7Days)} booked in the last 7 days`}/></div>
 <Panel title="Latest recommendations" aside={<span className="status-pill"><span className="status-dot"/>{data?.latestSnapshot?"Snapshot saved":"Awaiting first monitor run"}</span>}>{recs.length?<div className="draft-list">{recs.map((r:any,i:number)=><article className="draft-card" key={`${r.title}-${i}`}><span className="eyebrow">{r.severity==="warning"?"NEEDS ATTENTION":"RECOMMENDATION"}</span><h3>{r.title}</h3><p>{r.detail}</p><p><strong>Next step:</strong> {r.action}</p></article>)}</div>:<Empty>Run the monitor to create the first evidence-based recommendations. The first run establishes a baseline; it cannot prove a trend by itself.</Empty>}</Panel>
 <Panel title="Recent monitoring history">{data?.history?.length?<div className="table-wrap"><table className="data-table"><thead><tr><th>Checked at</th><th>Posts</th><th>Insights</th><th>Unique media views</th><th>Media views</th></tr></thead><tbody>{data.history.map((x:any)=><tr key={x.id}><td>{dateLabel(x.fetchedAt)}</td><td>{fmt(x.postCount)}</td><td>{fmt(x.insightsAvailable)}</td><td>{fmt(x.uniqueMediaViews)}</td><td>{fmt(x.mediaViews)}</td></tr>)}</tbody></table></div>:<Empty>No monitoring snapshots yet. Run the monitor or wait for the scheduled daily check.</Empty>}</Panel>
 <Panel title="What this system can and cannot know"><ul className="plain-list">{(data?.limitations||["Meta may not provide every metric for this Page or token.","Qualified-lead quality depends on recording real enquiries and outcomes.","Organic analytics cannot guarantee that only target guardians see posts.","This monitor generates recommendations; it does not automatically publish or change the content strategy."]).map((item:string)=><li key={item}>{item}</li>)}</ul><p className="panel-note">Daily monitoring runs with the scheduled automation endpoint. It saves Page snapshots and recommendations. It does not change publishing settings.</p></Panel></div>;
}

export function LearningLog() {
 const [data,setData]=useState<any>(null);const [notice,setNotice]=useState<Notice>(null);const load=useCallback(async()=>{try{setData(await api("learning"));}catch(e){setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load learning log."});}},[]);useEffect(()=>{void load();},[load]);
 return <div className="module-stack"><div className="module-intro"><div><h2>Evidence trail</h2><p>Audit events, experiments, and decisions stored by the application.</p></div><button className="subtle-button" onClick={load}><RefreshCw size={14}/> Refresh</button></div><NoticeBox notice={notice}/><Panel title="Recent audit events">{data?.audit?.length?<div className="timeline">{data.audit.map((x:any)=><div className="timeline-item" key={x.id}><div className="timeline-mark"><Check size={13}/></div><div><strong>{x.action.replaceAll("_"," ")}</strong><p>{dateLabel(x.createdAt)} · {x.actor}</p><small>{x.entityType||"System"}{x.entityId?` / ${x.entityId}`:""}</small></div></div>)}</div>:<Empty>No audit events yet. Actions such as draft generation and lead updates will appear here.</Empty>}</Panel><Panel title="Recorded decisions">{data?.decisions?.length?<div className="draft-list">{data.decisions.map((x:any)=><article className="draft-card" key={x.id}><span className="eyebrow">{x.category} · Confidence {Math.round(x.confidence*100)}%</span><h3>{x.hypothesis}</h3><p>{JSON.stringify(x.observation)}</p><small>{dateLabel(x.createdAt)}</small></article>)}</div>:<Empty>No autonomous decisions have been recorded. The system will not fabricate an evidence trail.</Empty>}</Panel></div>;
}

export function DocumentationModule() {
 const [status,setStatus]=useState<any>(null);const [error,setError]=useState("");useEffect(()=>{api("status").then(setStatus).catch(e=>setError(e instanceof Error?e.message:"Could not load system status."));},[]);
 return <div className="module-stack"><Panel title="Implementation guide"><div className="docs-grid">{[{title:"Product requirements",file:"docs/PRD.md",description:"Product scope, audience, and qualified-lead success metric."},{title:"Architecture",file:"docs/ARCHITECTURE.md",description:"Frontend, API modules, database, integrations, and deployment boundaries."},{title:"System rules",file:"docs/RULES.md",description:"Privacy, accuracy, safety, and organic-only constraints."},{title:"Implementation status",file:"docs/IMPLEMENTATION_STATUS.md",description:"Implemented workflows and remaining setup/testing requirements."},{title:"Production deployment",file:"docs/PRODUCTION_DEPLOYMENT.md",description:"Step-by-step Vercel, Neon and Meta setup with the staging checklist."},{title:"Database migration",file:"docs/DATABASE_MIGRATION.md",description:"Safe migration and recovery from old migration history."},{title:"AI models",file:"docs/AI_MODELS.md",description:"Which free models are used for Bangla content and lead triage, and why."},{title:"Requirements checklist",file:"docs/REQUIREMENTS_CHECKLIST.md",description:"Every instruction, its implementation, evidence and known limits."},{title:"Phases",file:"docs/PHASES.md",description:"Suggested build and verification sequence."},{title:"Design system",file:"docs/DESIGN.md",description:"Dashboard layout, responsive behavior, and component guidance."}].map(doc=><a className="doc-card" key={doc.file} href={`/docs/${doc.file.split("/").pop()}`} target="_blank" rel="noreferrer"><FileText size={18}/><div><strong>{doc.title}</strong><p>{doc.description}</p><code>{doc.file}</code></div><ExternalLink size={13}/></a>)}</div><p className="panel-note">Documentation files are in the project ZIP. Use them alongside this dashboard; this page does not pretend to render the full Markdown file contents.</p></Panel><Panel title="Live API status">{error?<NoticeBox notice={{kind:"error",text:error}}/>:status?<pre className="status-json">{JSON.stringify(status,null,2)}</pre>:<Busy/>}</Panel></div>;
}

export function OverviewWorkspace() {
 const overview = useQuery({ queryKey: ["overview"], queryFn: () => api<any>("overview"), refetchInterval: 30_000, retry: 1 });
 const data = overview.data;
 const notice: Notice = overview.error ? { kind: "error", text: overview.error instanceof Error ? overview.error.message : "Could not load overview." } : null;
 return <div className="module-stack"><NoticeBox notice={notice}/>{overview.isLoading&&<Busy label="Loading current workspace data…"/>}<div className="metrics metrics-five"><Metric label="Qualified leads" value={fmt(data?.qualifiedLeads)} foot="Stored qualification status"/><Metric label="Confirmed bookings" value={fmt(data?.bookings)} foot="Leads marked booked"/><Metric label="Unique media views" value={fmt(data?.totalUniqueMediaViews)} foot={data?.totalUniqueMediaViews===null||data?.totalUniqueMediaViews===undefined?"Unavailable until Meta returns this insight":"Proxy for attention; not exact reach or unique people reached"}/><Metric label="Media views" value={fmt(data?.totalViews)} foot={data?.totalViews===null||data?.totalViews===undefined?"Unavailable until Meta returns media-view insights":"Sum of returned media-view values"}/><Metric label="Saved drafts" value={fmt(data?.drafts)} foot={`${fmt(data?.scheduled)} planned in calendar`}/></div><Panel title="System readiness" aside={<span className="status-pill"><span className="status-dot"/>{data?.globalAutomationPaused!==false?"Paused safely":"Automation unpaused"}</span>}><div className="readiness-list"><Readiness name="Facebook Page baseline" ready={Boolean(data?.lastAnalyzedAt)} detail={data?.pageName?`${data.pageName} · ${data.postCount??0} posts fetched`:"Connect and analyze your Page to import real data."}/><Readiness name="Qualified lead outcomes" ready={Boolean(data?.qualifiedLeads||data?.bookings)} detail="Use Qualified Leads to record enquiries and booking outcomes."/><Readiness name="Agent Mode" ready={data?.agentMode===true} detail={data?.agentMode?"Autonomous campaign is on.":"OFF by default. Must be explicitly enabled by an administrator."}/><Readiness name="Live publishing" ready={data?.publishMode==="live"} detail={data?.publishMode==="live"?"Live mode configured; confirm Meta permissions and Messenger URL before relying on automation.":"Dry-run mode is active. Set META_PUBLISH_MODE=live only after staging tests."}/></div></Panel><Panel title="What to do next"><div className="timeline"><div className="timeline-item"><div className="timeline-mark">1</div><div><strong>Verify Meta access</strong><p>Open Page Analyzer and test the actual token and granted permissions.</p></div></div><div className="timeline-item"><div className="timeline-mark">2</div><div><strong>Test the agent campaign</strong><p>Configure the verified Messenger URL and live mode, then run a staging photo/Reel publish before relying on automation.</p></div></div><div className="timeline-item"><div className="timeline-mark">3</div><div><strong>Review captured leads</strong><p>Webhook messages are triaged by AI; correct Qualified/Unqualified/Booked outcomes so the agent learns from real lead quality.</p></div></div></div></Panel></div>;
}
function Metric({label,value,foot}:{label:string;value:string;foot:string}){return <div className="metric"><div className="metric-top">{label}</div><div className="metric-value">{value}</div><div className="metric-foot">{foot}</div></div>;}


function ChecksView({data}:{data:any}){return <div className="readiness-list" role="region" aria-label="Publish checks"><div><strong>{data.ok?"Ready to publish":"Not ready: fix the failed checks"}</strong><p className="panel-note">Mode: {data.publishMode}. {data.publishMode!=="live"?"Dry-run: nothing is sent to Facebook.":"Live: Publish sends this to Facebook."}</p></div>{data.checks.map((c:any)=><Readiness key={c.id} name={c.label} ready={c.ok} detail={c.detail||(c.ok?"Passed":"Failed")}/>)}{data.finalCaption&&<details><summary>Exact caption that will be posted</summary><p className="draft-caption">{data.finalCaption}</p></details>}{Array.isArray(data.reelFrames)&&<details><summary>Reel frames, in order</summary><ol className="plain-list">{data.reelFrames.map((t:string,i:number)=><li key={i}>{t}</li>)}</ol></details>}</div>;}

function AiHealthPanel({settings}:{settings:any}){
  const [rows,setRows]=useState<any[]|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const usage=settings?.integrations?.aiUsage;
  async function test(){setBusy(true);setError("");try{const r=await api<any>("ai/self-test",send("POST",{}));setRows(r.data||[]);}catch(e){setError(e instanceof Error?e.message:"Self-test failed.");}finally{setBusy(false);}}
  return <Panel title="Free AI health" aside={<button className="subtle-button" onClick={test} disabled={busy}>{busy?<LoaderCircle size={13} className="spin"/>:<Sparkles size={13}/>} Test every model</button>}><p className="panel-note">Content chain, in order: {(settings?.integrations?.aiChain||[]).join("  →  ")||"none configured (add GEMINI_API_KEY and/or GROQ_API_KEY)"}. {usage&&usage.usedToday!==null?`AI requests today: ${usage.usedToday} of ${usage.dailyLimit} (resets at midnight Bangladesh time).`:""}</p>{error&&<NoticeBox notice={{kind:"error",text:error}}/>}{rows&&<div className="table-wrap"><table className="data-table"><thead><tr><th>Used for</th><th>Model</th><th>Result</th><th>Bangla output</th><th>Time</th></tr></thead><tbody>{rows.map((r:any)=><tr key={`${r.task}:${r.provider}:${r.model}`}><td>{r.task}</td><td>{r.provider}:{r.model}</td><td>{r.ok?"Working":`${r.category||"Failed"}`}{r.message&&<small className="table-subtext">{r.message}</small>}</td><td>{r.ok?(r.banglaOutput?"Yes":"No"):"—"}</td><td>{(r.ms/1000).toFixed(1)}s</td></tr>)}</tbody></table></div>}<p className="panel-note">The test sends one tiny request per model and counts toward today’s free quota. If a model is rate-limited or retired, the agent automatically uses the next one in the chain.</p></Panel>;
}

function DiagnosticsPanel(){
  const [data,setData]=useState<any>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState("");
  async function run(){setBusy(true);setError("");try{setData(await api<any>("diagnostics"));}catch(e){setError(e instanceof Error?e.message:"Diagnostics failed.");}finally{setBusy(false);}}
  return <Panel title="Deployment self-check" aside={<button className="subtle-button" onClick={run} disabled={busy}>{busy?<LoaderCircle size={13} className="spin"/>:<ShieldCheck size={13}/>} Run checks</button>}>{error&&<NoticeBox notice={{kind:"error",text:error}}/>}{data?<div className="readiness-list">{data.checks.map((c:any)=><Readiness key={c.id} name={c.label} ready={c.ok} detail={c.detail||(c.ok?"OK":"Needs attention")}/>)}</div>:<p className="panel-note">Verifies on the live server: database + migrations, Bangla fonts, FFmpeg for Reels, Messenger URL, Meta and AI credentials. Run it after every deployment.</p>}</Panel>;
}

function BusinessProfilePanel(){
  const [form,setForm]=useState<any>(null);const [notice,setNotice]=useState<Notice>(null);const [busy,setBusy]=useState(false);
  const lines=(v:string)=>v.split("\n").map(x=>x.trim()).filter(Boolean);
  useEffect(()=>{void api<any>("business-profile").then(r=>{const d=r.data;setForm({name:d.name,description:d.description,serviceAreas:d.serviceAreas.join("\n"),supportedPrograms:d.supportedPrograms.join("\n"),trustedFacts:d.trustedFacts.join("\n"),prohibitedClaims:d.prohibitedClaims.join("\n"),configured:d.configured});}).catch(e=>setNotice({kind:"error",text:e instanceof Error?e.message:"Could not load the business profile."}));},[]);
  async function save(e:FormEvent){e.preventDefault();setBusy(true);setNotice(null);try{await api("business-profile",{method:"PUT",body:JSON.stringify({name:form.name,description:form.description,serviceAreas:lines(form.serviceAreas),supportedPrograms:lines(form.supportedPrograms),trustedFacts:lines(form.trustedFacts),prohibitedClaims:lines(form.prohibitedClaims)})});setNotice({kind:"success",text:"Business profile saved. The agent will use only these facts and will reject drafts that contain the prohibited claims."});}catch(err){setNotice({kind:"error",text:err instanceof Error?err.message:"Could not save the profile."});}finally{setBusy(false);}}
  if(!form)return <Panel title="Business facts the agent may use"><Busy/></Panel>;
  const set=(k:string)=>(e:any)=>setForm({...form,[k]:e.target.value});
  return <Panel title="Business facts the agent may use"><form className="workspace-form" onSubmit={save}><p className="panel-note">The agent never invents business facts. Add only what is true; one item per line. {form.configured?"":"Not saved yet: defaults are in use."}</p><div className="form-grid"><label>Business name<input required minLength={2} value={form.name} onChange={set("name")}/></label><label>Service areas<textarea rows={3} value={form.serviceAreas} onChange={set("serviceAreas")} placeholder="চট্টগ্রাম&#10;পাঁচলাইশ"/></label></div><label>One-line description<textarea required rows={2} value={form.description} onChange={set("description")}/></label><label>Programs / curricula you really support<textarea rows={3} value={form.supportedPrograms} onChange={set("supportedPrograms")} placeholder="বাংলা ভার্সন&#10;ইংরেজি ভার্সন&#10;ও-লেভেল / এ-লেভেল"/></label><label>Verified facts the agent may state<textarea rows={3} value={form.trustedFacts} onChange={set("trustedFacts")} placeholder="Example: আমরা অভিভাবকের প্রয়োজন অনুযায়ী টিউটর খোঁজার ব্যবস্থা করি"/></label><label>Extra phrases the agent must never use<textarea rows={3} value={form.prohibitedClaims} onChange={set("prohibitedClaims")} placeholder="Built-in blocks already cover guarantees, 100%, prices, discounts and testimonials."/></label><button className="action-button" disabled={busy}>{busy?<LoaderCircle size={15} className="spin"/>:<Check size={15}/>} Save business facts</button><NoticeBox notice={notice}/></form></Panel>;
}
